//! Table-driven TeX compliance.  The cases are not written by hand: they are
//! generated by walking [`satex::builtins::initial_meanings`], so a primitive
//! added to `src/builtins.rs` is probed without anyone remembering to add a
//! test.  Every expectation comes from running the real engine
//! (`pdftex`/`xetex`/`luatex` with `-ini`), never from a table of TeX
//! knowledge in this file.
//!
//! Each probe is one line of a batch document.  The line opens a group, resets
//! the state the witnesses read, runs the probe, then records the probe's own
//! answer `\zR` and three witness macros that read the state back.  satex
//! analyzes the very same file, so line numbers, `\inputlineno` and `\jobname`
//! agree, and a definition is matched to its probe by `Definition::span.line`.
//!
//! The comparison follows the verdict `builtins::verdict` gives the primitive:
//!
//! - `Exact`: satex's answer equals the engine's.
//! - `Approximated`: satex's answer contains the engine's (an equal answer, or
//!   a widened one).
//! - `Unsupported`: containment too, and where the operand cannot be pinned
//!   down satex must widen and say so with a diagnostic.
//!
//! One relation holds for every verdict: if satex gives a single confident
//! answer that differs from the engine's, that is silent wrongness and fails.
//! It is checked on the witnesses as well as on the answer, which is what
//! catches a widened value left beside a stale binding.
//!
//! `SATEX_COMPLIANCE=full` runs the whole cross product.  The default runs the
//! meaning probe for every primitive, the behavioral probe for every primitive
//! that has one, and a representative slice of the context and edge-value
//! dimensions.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use satex::builtins::{
    self, Arith, BoxCmd, CodeTable, Cond, Convert, Deferred, FontParam, LastItem, LoadKind, Material, ModeCmd, Prefix,
    Primitive, Special, Syntax, TextOf, Typeset, Verdict,
};
use satex::config::{Config, Engine, Interaction, Load, Texmf};
use satex::machine::{Analysis, Machine};
use satex::plugin::Kernel;
use satex::tex::{Meaning, RegKind};

// The document each probe is written into.

/// Without a format the catcodes are INITEX's (tex.web § 232), so only the
/// grouping, parameter and superscript characters have to be declared.  This
/// is line 1 of every batch, in the engine's file and in satex's alike.
const PRELUDE: &str = "\\catcode`\\{=1 \\catcode`\\}=2 \\catcode`\\#=6 \\catcode`\\^=7 \\immediate\\openout9=zout";

/// LuaTeX's INITEX hides its own extensions behind `luatex`-prefixed names
/// until `tex.enableprimitives` is called (LuaTeX manual, "Enabling
/// primitives"), which every LuaTeX format does.  The oracle has to be the
/// engine a document really meets, so the engine's copy of line 1 turns them
/// on.  satex's copy stays the prelude, and both files keep the same line
/// numbering.
const LUA_PRELUDE: &str = "\\directlua{tex.enableprimitives(\"\",tex.extraprimitives())}";

/// The state every probe starts from, so a probe that leaks past its group
/// cannot make the next one pass by accident.
const RESET: &str = "\\global\\let\\zR\\relax \\global\\let\\zX\\relax \\global\\let\\zY\\relax \\global\\let\\zZ\\relax \\count255=1 \\dimen255=1pt \\skip255=1pt plus 1pt \\muskip255=1mu \\toks255={q}\
\\count0=1 \\dimen0=1pt \\skip0=1pt \\toks0={q}\\setbox255=\\hbox{}\\setbox0=\\hbox{}\
\\def\\victim{v}\\chardef\\cvictim=7 \\lccode`\\A=`\\a \\uccode`\\a=`\\A \\sfcode`\\A=1000 \
\\catcode`\\@=12 \\escapechar=92 \\closein0 \\closein3 ";

/// What the witnesses read back.  A widening is sound only if it covers the
/// work the construct could have done, not only the value it returns, so each
/// probe reads the registers, codes, meanings and structure a primitive could
/// have touched.  `\zX` is the register file, `\zY` the per-character tables
/// and the meanings, `\zZ` the group, mode, stream and parameter state.
const WITNESS_X: &str = "\\edef\\zX{\\the\\count255;\\the\\dimen255;\\the\\skip255;\\the\\muskip255;\\the\\toks255;\
\\the\\wd255;\\the\\ht255;\\the\\dp255;\\the\\count0;\\the\\dimen0;\\the\\skip0;\\the\\toks0;\\the\\wd0}";
const WITNESS_Y: &str = "\\edef\\zY{\\the\\catcode`\\@;\\the\\lccode`\\A;\\the\\uccode`\\a;\\the\\sfcode`\\A;\
\\the\\mathcode`\\A;\\the\\escapechar;\\the\\endlinechar;\\meaning\\victim;\\meaning\\cvictim;\\meaning\\zabsent}";
const WITNESS_Z: &str = "\\edef\\zZ{\\the\\currentgrouplevel;\\the\\currentiflevel;\
\\ifvmode V\\else\\ifhmode H\\else\\ifmmode M\\else X\\fi\\fi\\fi;\\ifinner I\\else O\\fi;\
\\ifeof0 E\\else N\\fi;\\ifeof3 E\\else N\\fi;\\the\\hsize;\\the\\tolerance;\\the\\everypar;\\fontname\\font}";

/// The macros a probe's answer and witnesses are read from.
const SLOTS: [&str; 4] = ["zR", "zX", "zY", "zZ"];

// Dimensions.  Each is a context a primitive can be met in that the
// interpreter has to get right, with the reason it is here.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Dim {
    /// The primitive on its own, at the outer vertical mode.
    Plain,
    /// Under a conditional whose test satex cannot decide (tex.web § 498: the
    /// engine takes one branch, satex must cover both).  `\uniformdeviate 1`
    /// is 0 in every engine, so the engine's branch is determined while
    /// satex's is not.
    Undecided,
    /// `\globaldefs` makes every assignment global (tex.web § 1214), so an
    /// assignment satex records as local outlives the group it was made in.
    GlobalDefs,
    /// Inside a group that ends (tex.web § 281 `unsave`): the effect must be
    /// undone, and a widening must be undone with it.
    Group,
    /// A register or code written through an index satex cannot pin down
    /// (tex.web § 433 `scan_eight_bit_int`): every register it could name has
    /// to widen, not just the one the engine picked.
    Unpinned,
    /// The body read from another file (tex.web § 537 `\input`): a scan may
    /// cross the file boundary, and `\everyeof` fires at its end.
    File,
    /// The body read back from a macro expansion (tex.web § 389 `macro_call`),
    /// so the tokens reach the stomach from a token list, not from a file.
    Expansion,
    /// The body re-tokenized from characters (eTeX manual § 3.9
    /// `\scantokens`): a pseudo-file boundary with the catcodes now in force.
    Rescan,
    /// The body inside restricted horizontal mode (tex.web § 1090): the mode
    /// decides what a command means.
    HMode,
    /// The body inside internal vertical mode (tex.web § 1070).
    VMode,
}

impl Dim {
    fn tag(self) -> &'static str {
        match self {
            Dim::Plain => "plain",
            Dim::Undecided => "undecided",
            Dim::GlobalDefs => "globaldefs",
            Dim::Group => "group",
            Dim::Unpinned => "unpinned",
            Dim::File => "file",
            Dim::Expansion => "expansion",
            Dim::Rescan => "rescan",
            Dim::HMode => "hmode",
            Dim::VMode => "vmode",
        }
    }

    /// Whether the context alone may force satex to widen, so an `Exact`
    /// primitive is held to containment instead of equality here.
    fn may_widen(self) -> bool {
        matches!(self, Dim::Undecided | Dim::Unpinned)
    }

    /// Whether the probe's own answer can still be read where the witnesses
    /// are.  Under [`Dim::File`] it is defined in the included file, and under
    /// [`Dim::Group`] the group that ends takes it back again, which is the
    /// very thing that dimension checks.  The witnesses, which stay outside,
    /// carry the comparison there.
    fn answer_is_on_the_line(self) -> bool {
        !matches!(self, Dim::File | Dim::Group)
    }
}

const CONTEXTS: [Dim; 9] = [
    Dim::Undecided,
    Dim::GlobalDefs,
    Dim::Group,
    Dim::Unpinned,
    Dim::File,
    Dim::Expansion,
    Dim::Rescan,
    Dim::HMode,
    Dim::VMode,
];

/// The numeric boundaries tex.web itself names: zero and its neighbors, the
/// 31-bit ends `scan_int` checks (§ 445), `\maxdimen` and the 2^30 boundary
/// (§ 421), the four- and eight-bit register ranges (§ 433), and the scaled
/// point rounding cases around 16383.99998pt (§§ 448-460).
const EDGE_INTS: [&str; 13] =
    ["0", "1", "-1", "15", "16", "255", "256", "32767", "1073741823", "1073741824", "2147483647", "-2147483648", "-0"];

const EDGE_DIMENS: [&str; 10] = [
    "0pt",
    "1sp",
    "-1sp",
    "0.00000762939453125pt",
    "0.0000076293945312pt",
    "16383.99998pt",
    "16383.99999pt",
    "16384pt",
    "-16384pt",
    "1073741823sp",
];

// Probe templates, chosen by the `Primitive` variant so the table in
// `builtins.rs` drives the suite.

/// A probe body with its placeholders still in it: `%I%` a register index,
/// `%S%` an input stream number, `%N%` an integer literal, `%D%` a dimension
/// literal, `%C%` a character.
struct Template {
    body: String,
}

impl Template {
    fn new(body: impl Into<String>) -> Self {
        Template { body: body.into() }
    }

    fn has(&self, what: &str) -> bool {
        self.body.contains(what)
    }

    fn fill(&self, with: Fill<'_>) -> String {
        self.body
            .replace("%I%", with.index)
            .replace("%S%", with.index)
            .replace("%T%", with.index)
            .replace("%N%", with.int)
            .replace("%D%", with.dimen)
    }
}

/// What a template's placeholders are filled with.
#[derive(Clone, Copy)]
struct Fill<'a> {
    index: &'a str,
    int: &'a str,
    dimen: &'a str,
}

impl Default for Fill<'_> {
    fn default() -> Self {
        Fill { index: "7", int: "3", dimen: "3pt" }
    }
}

/// The behavioral probe for a primitive, or why there is none.  The match on
/// [`Primitive`] is exhaustive, so a new variant cannot slip in unprobed and
/// unlisted.  Where one variant covers primitives of different syntax the arm
/// matches on the name as well.  The value expected is still the engine's.
fn template(name: &str, p: Primitive) -> Result<Template, &'static str> {
    use Primitive as P;
    let cs = format!("\\{name}");
    let t = |s: String| Ok(Template::new(s));
    match p {
        // Definitions and expansion.
        P::Def { expand, .. } => {
            let body = if expand { "a\\noexpand\\relax" } else { "a\\relax" };
            t(format!("{cs}\\zq#1{{[#1]{body}}}\\zq{{x}}\\edef\\zR{{\\meaning\\zq}}"))
        }
        P::Let { future, .. } => {
            if future {
                t(format!("{cs}\\zq\\relax\\relax\\edef\\zR{{\\meaning\\zq}}"))
            } else {
                t(format!("{cs}\\zq=\\relax \\edef\\zR{{\\meaning\\zq}}"))
            }
        }
        P::Prefix(Prefix::Global) => {
            t(format!("\\begingroup{cs}\\count%I%=%N% \\endgroup\\edef\\zR{{\\the\\count%I%}}"))
        }
        P::Prefix(Prefix::Long | Prefix::Outer | Prefix::Protected) => {
            t(format!("{cs}\\def\\zq#1{{[#1]}}\\edef\\zR{{\\meaning\\zq}}"))
        }
        P::Prefix(Prefix::Immediate) => t(format!("{cs}\\write9{{im}}\\edef\\zR{{done}}")),
        P::ExpandAfter => t(format!("\\def\\za{{\\zb}}\\def\\zb{{X}}\\edef\\zR{{[{cs}\\meaning\\za]}}")),
        P::NoExpand => t(format!("\\def\\za{{X}}\\edef\\zR{{[{cs}\\za\\za]}}")),
        P::DontExpand => Err("an internal marker for `\\noexpand`, not a control sequence"),
        P::SkipCrossing { .. } => Err("satex's own marker for a conditional a file boundary interrupted"),
        P::Csname => t(format!("\\expandafter\\def{cs} zqq\\endcsname{{Y}}\\edef\\zR{{[{cs} zqq\\endcsname]}}")),
        P::Endcsname => t(format!("\\expandafter\\def\\csname zqq{cs}{{Y}}\\edef\\zR{{[\\csname zqq{cs}]}}")),
        P::BeginCsname => t(format!("\\edef\\zR{{[{cs} zabsent\\endcsname]}}")),
        P::LastNamedCs => t(format!("\\ifcsname relax\\endcsname\\edef\\zR{{[\\expandafter\\string{cs}]}}\\fi")),
        P::Text(TextOf::String) => t(format!("\\edef\\zR{{[{cs}\\relax][{cs} A]}}")),
        P::Text(TextOf::Meaning) => t(format!("\\edef\\zR{{[{cs}\\relax][{cs}\\victim][{cs}\\zabsent][{cs}\\count]}}")),
        P::Text(TextOf::The) => t(format!("\\count%I%=%N% \\edef\\zR{{[{cs}\\count%I%][{cs}\\catcode`\\@]}}")),
        P::Text(TextOf::Number) => t(format!("\\edef\\zR{{[{cs}%N%][{cs}\\count%I%]}}")),
        P::Text(TextOf::Roman) => t(format!("\\edef\\zR{{[{cs}1984][{cs}0]}}")),
        P::Text(TextOf::Detokenize) => t(format!("\\edef\\zR{{[{cs}{{\\foo a \\relax}}]}}")),
        P::Text(TextOf::JobName) => t(format!("\\edef\\zR{{[{cs}]}}")),
        P::Reinject => t(format!("\\def\\za{{X}}\\edef\\zR{{[{cs}{{\\za}}]}}")),
        P::ScanTokens { .. } => t(format!("{cs}{{\\def\\zR{{S}}}}")),
        P::Use(_) => Err("an expl3 name, defined by `expl3-code.tex`, not by the engine"),
        P::Expanded => t(format!("\\def\\za{{X}}\\edef\\zR{{[{cs}{{\\za}}]}}")),

        // Conditionals.
        P::If(c) => conditional(name, c),
        P::Else => t("\\iffalse\\def\\zR{A}\\else\\def\\zR{B}\\fi".to_string()),
        P::Or => t("\\ifcase1 \\def\\zR{a}\\or\\def\\zR{b}\\else\\def\\zR{c}\\fi".to_string()),
        P::Fi => t("\\iftrue\\def\\zR{T}\\fi".to_string()),
        P::Unless => t(format!("{cs}\\ifnum1=2 \\def\\zR{{T}}\\else\\def\\zR{{F}}\\fi")),
        P::BeginGroup => t(format!("{cs}\\count%I%=%N% \\endgroup\\edef\\zR{{\\the\\count%I%}}")),
        P::EndGroup => t(format!("\\begingroup\\count%I%=%N% {cs}\\edef\\zR{{\\the\\count%I%}}")),
        // The two are distinct commands (tex.web § 265), so the probe comes
        // from what the meaning holds, not from the name it was reached by.
        P::Defer(Deferred::Group) => t(format!("\\def\\za{{\\def\\zR{{A}}}}\\begingroup{cs}\\za\\endgroup")),
        P::Defer(Deferred::Assignment) => t(format!("\\def\\za{{\\def\\zR{{B}}}}{cs}\\za\\count%I%=%N% ")),

        // Registers and arithmetic.
        P::Allocate(_) => Err("LaTeX's allocator, defined by the format, not an engine primitive"),
        P::Register(RegKind::Box) => t(format!(
            "\\setbox%I%=\\hbox{{}}\\setbox1={cs}%I% \\edef\\zR{{\\ifvoid%I% V\\else N\\fi\\ifvoid1 V\\else N\\fi}}"
        )),
        P::Register(k) => {
            let value = register_value(k);
            t(format!("{cs}%I%={value} \\edef\\zR{{\\the{cs}%I%}}"))
        }
        P::RegisterDef(_) => t(format!("{cs}\\zq=%N% \\edef\\zR{{\\meaning\\zq}}")),
        P::FontDef => t(format!("{cs}\\zq=cmr10 \\edef\\zR{{\\fontname\\zq,\\meaning\\zq}}")),
        P::OpenIn => t(format!("{cs}%S%=zprobe \\edef\\zR{{\\ifeof%S% E\\else N\\fi}}")),
        P::CloseIn => t(format!("\\openin%S%=zprobe {cs}%S% \\edef\\zR{{\\ifeof%S% E\\else N\\fi}}")),
        P::Read => t(format!("\\openin%T%=zprobe {cs}%T% to\\zq \\edef\\zR{{[\\zq]}}")),
        P::Arith(a) => {
            let by = match a {
                Arith::Advance => "3",
                Arith::Multiply => "3",
                Arith::Divide => "2",
            };
            t(format!("\\count%I%=6 {cs}\\count%I% by {by} \\edef\\zR{{\\the\\count%I%}}"))
        }
        P::IntegerParameter => t(format!("{cs}=%N% \\edef\\zR{{\\the{cs}}}")),
        P::DimenParameter => t(format!("{cs}=%D% \\edef\\zR{{\\the{cs}}}")),
        P::GlueParameter { mu: false } => t(format!("{cs}=%D% plus 1fil minus 2pt \\edef\\zR{{\\the{cs}}}")),
        P::GlueParameter { mu: true } => t(format!("{cs}=3mu plus 1fil \\edef\\zR{{\\the{cs}}}")),
        P::TokensParameter => t(format!("{cs}={{ab\\relax}}\\edef\\zR{{[\\the{cs}]}}")),
        P::CatcodeAssign => t(format!("{cs}%C%=11 \\edef\\zR{{\\the{cs}%C%,\\the{cs}`\\B}}")),
        P::CharCode(_) => t(format!("{cs}%C%=%N% \\edef\\zR{{\\the{cs}%C%,\\the{cs}`\\B}}")),
        P::CaseShift(CodeTable::Lower) => t(format!("\\lccode`\\B=`\\c {cs}{{\\def\\zR{{XBY}}}}")),
        P::CaseShift(CodeTable::Upper) => t(format!("\\uccode`\\b=`\\C {cs}{{\\def\\zR{{xby}}}}")),
        P::CaseShift(_) => Err("only `\\lowercase` and `\\uppercase` shift case"),

        // Files and job control.
        P::Load(LoadKind::Input) => t(format!("{cs} zin \\edef\\zR{{[\\zin]}}")),
        P::Load(_) => Err("a LaTeX loader, defined by the format, not an engine primitive"),
        P::Endinput => t("\\input zend \\edef\\zR{[\\zend]}".to_string()),
        P::End => Err("ends the run, so it cannot share a document with other probes"),
        P::Message { error: false } => t(format!("{cs}{{hi}}\\edef\\zR{{done}}")),
        P::Message { error: true } => t(format!("\\errhelp={{}}{cs}{{hi}}\\edef\\zR{{done}}")),
        P::Write => t(format!("\\immediate{cs}9{{w}}\\edef\\zR{{done}}")),
        P::Expr(k) => {
            let expression = match k {
                RegKind::Count => "7*3/2",
                RegKind::Dimen => "%D%*3/4",
                RegKind::Skip => "%D% plus 2fil-3pt",
                RegKind::MuSkip => "3mu*3/2",
                _ => return Err("no expression type for this register kind"),
            };
            t(format!("\\edef\\zR{{\\the{cs} {expression}\\relax}}"))
        }
        P::Relax => t(format!("{cs}\\edef\\zR{{done}}")),
        P::IgnoreSpaces => t(format!("\\def\\za{{ }}{cs}\\za\\edef\\zR{{done}}")),

        // Codes, boxes and fonts.
        P::Special(Special::BoxDimen) => t(format!("\\setbox%I%=\\hbox{{}}{cs}%I%=%D% \\edef\\zR{{\\the{cs}%I%}}")),
        P::Special(Special::ParShape) => {
            t(format!("{cs}=2 1pt 2pt 3pt 4pt \\edef\\zR{{\\the{cs},\\the\\parshapelength2}}"))
        }
        P::Special(Special::Penalties) => t(format!("{cs}=2 100 200 \\edef\\zR{{\\the{cs}0,\\the{cs}1,\\the{cs}2}}")),
        P::Special(Special::CharClass) => t(format!("{cs}%C%=3 \\edef\\zR{{\\the{cs}%C%}}")),
        P::Special(Special::InterCharToks) => t(format!("{cs}1 2={{ab}}\\edef\\zR{{[\\the{cs}1 2]}}")),
        P::Special(Special::UCode { num: true, .. }) => t(format!("{cs}%C%=%N% \\edef\\zR{{\\the{cs}%C%}}")),
        P::Special(Special::UCode { math: true, num: false }) => {
            t(format!("{cs}%C%=0 1 65 \\edef\\zR{{\\the{cs}%C%}}"))
        }
        P::Special(Special::UCode { math: false, num: false }) => t(format!("{cs}%C%=1 65 \\edef\\zR{{\\the{cs}%C%}}")),
        P::FontParam(FontParam::Dimen) => t(format!("{cs}1\\nullfont=%D% \\edef\\zR{{\\the{cs}1\\nullfont}}")),
        P::FontParam(FontParam::HyphenChar | FontParam::SkewChar) => {
            t(format!("{cs}\\nullfont=%N% \\edef\\zR{{\\the{cs}\\nullfont}}"))
        }
        P::FontParam(FontParam::CharCode(_)) => {
            t(format!("\\font\\zf=cmr10 {cs}\\zf 65=5 \\edef\\zR{{\\the{cs}\\zf 65,\\the{cs}\\zf 66}}"))
        }
        // Read from the TFM tag first: `A` has a lig/kern program, `B` none.
        P::FontParam(FontParam::TagCode { .. }) => t(format!(
            "\\font\\zf=cmr10 \\edef\\zA{{\\the{cs}\\zf 65,\\the{cs}\\zf 66}}{cs}\\zf 66=5 {cs}\\zf 97=-7 \
             \\edef\\zR{{\\zA;\\the{cs}\\zf 66,\\the{cs}\\zf 97}}"
        )),
        P::FontIdent(_) => t(format!("\\edef\\zR{{\\fontname{cs},\\meaning{cs}}}")),

        // Expandable text of the engine's own.
        P::Convert(c) => convert(name, c),
        P::LastItem(item) => last_item(name, item),

        // Page material.  satex builds no pages, so the probe asks what the
        // engine can still tell from the box it went into.
        P::Typeset(Typeset::Number) => t(format!("\\setbox%I%=\\hbox{{{cs}%N% }}\\edef\\zR{{\\the\\wd%I%}}")),
        P::Typeset(Typeset::Dimen) if name == "kern" => {
            t(format!("\\setbox%I%=\\hbox{{{cs}%D% }}\\edef\\zR{{\\the\\wd%I%,\\the\\lastkern}}"))
        }
        P::Typeset(Typeset::Plain) if name == "unskip" || name == "unkern" || name == "unpenalty" => {
            t(format!("\\setbox%I%=\\hbox{{\\kern3pt{cs}}}\\edef\\zR{{\\the\\wd%I%}}"))
        }
        P::Typeset(_) => Err("math-mode material, which needs the math fonts a format loads"),
        // Page material, probed by what the engine can still be asked about
        // it: the box it went into, and the mode it left behind.
        P::Mode(ModeCmd::Box(BoxCmd::HBox | BoxCmd::VBox | BoxCmd::VTop)) => {
            t(format!("\\setbox%I%={cs} to %D%{{}}\\edef\\zR{{\\the\\wd%I%,\\the\\ht%I%,\\the\\dp%I%}}"))
        }
        P::Mode(ModeCmd::Box(BoxCmd::Copy)) => t(format!(
            "\\setbox%I%=\\hbox{{}}\\setbox1={cs}%I% \\edef\\zR{{\\ifvoid%I% V\\else N\\fi\\ifvoid1 V\\else N\\fi}}"
        )),
        P::Mode(ModeCmd::Horizontal(Material::Unpackage { .. })) => t(format!(
            "\\setbox%I%=\\hbox{{}}\\setbox1=\\hbox{{{cs}%I% }}\\edef\\zR{{\\ifvoid%I% V\\else N\\fi,\\the\\wd1}}"
        )),
        P::Mode(ModeCmd::Vertical(Material::Unpackage { .. })) => t(format!(
            "\\setbox%I%=\\vbox{{}}\\setbox1=\\vbox{{{cs}%I% }}\\edef\\zR{{\\ifvoid%I% V\\else N\\fi,\\the\\ht1}}"
        )),
        P::Mode(ModeCmd::Par | ModeCmd::StartPar { .. } | ModeCmd::QuitVMode) => {
            t(format!("{cs}\\edef\\zR{{\\ifhmode H\\else\\ifvmode V\\else M\\fi\\fi,\\ifinner I\\else O\\fi}}"))
        }
        P::Mode(ModeCmd::Horizontal(Material::Glue)) => {
            t(format!("\\setbox%I%=\\hbox{{{cs}%D% }}\\edef\\zR{{\\the\\wd%I%,\\the\\lastskip}}"))
        }
        P::Mode(ModeCmd::Vertical(Material::Glue)) => {
            t(format!("\\setbox%I%=\\vbox{{{cs}%D% }}\\edef\\zR{{\\the\\ht%I%}}"))
        }
        // `\hfil` and its relatives take no dimension (tex.web § 1058).
        P::Mode(ModeCmd::Horizontal(Material::Fil(_))) => {
            t(format!("\\setbox%I%=\\hbox{{{cs}}}\\edef\\zR{{\\the\\wd%I%}}"))
        }
        P::Mode(ModeCmd::Vertical(Material::Fil(_))) => {
            t(format!("\\setbox%I%=\\vbox{{{cs}}}\\edef\\zR{{\\the\\ht%I%}}"))
        }
        P::Mode(ModeCmd::Horizontal(Material::Rule)) | P::Mode(ModeCmd::Vertical(Material::Rule)) => {
            t(format!("\\setbox%I%=\\vbox{{{cs} height %D% width %D% }}\\edef\\zR{{\\the\\ht%I%,\\the\\wd%I%}}"))
        }
        // `\raise` and `\lower` shift a box in a horizontal list, `\moveleft`
        // and `\moveright` one in a vertical list (tex.web § 1073).
        P::Mode(ModeCmd::Shift { vertical: true }) => {
            t(format!("\\setbox%I%=\\hbox{{{cs}%D%\\hbox{{}}}}\\edef\\zR{{\\the\\ht%I%,\\the\\dp%I%}}"))
        }
        P::Mode(ModeCmd::Shift { vertical: false }) => {
            t(format!("\\setbox%I%=\\vbox{{{cs}%D%\\hbox{{}}}}\\edef\\zR{{\\the\\wd%I%,\\the\\ht%I%}}"))
        }
        P::Mode(_) => Err("page material whose effect is the typeset page, not a value"),

        // Payloads satex records rather than replays.
        P::Pdf(_) => Err("a payload for the PDF writer, which this run never reaches"),
        P::Lua(_) => Err("the Lua interface, covered by tests/it/lua.rs against a real host"),
        P::Docstrip(_) => Err("a docstrip batch-file command, not run as TeX"),
        P::LuaCall { .. } => Err("a control sequence Lua defines at run time, not an initial meaning"),
        P::Command(Syntax::SetBox) => {
            t(format!("{cs}%I%=\\hbox{{}}\\edef\\zR{{\\ifvoid%I% V\\else N\\fi,\\the\\wd%I%}}"))
        }
        P::Command(Syntax::ReadLine) => t(format!("\\openin%T%=zprobe {cs}%T% to\\zq \\edef\\zR{{[\\zq]}}")),
        P::Command(Syntax::OpenOut) => {
            t(format!("\\immediate{cs}5=zw \\immediate\\write5{{x}}\\immediate\\closeout5 \\edef\\zR{{done}}"))
        }
        P::Command(Syntax::CloseOut) => t(format!("\\immediate\\openout5=zw \\immediate{cs}5 \\edef\\zR{{done}}")),
        P::Command(Syntax::FamilyFont) => t(format!("{cs}0=\\nullfont \\edef\\zR{{\\fontname{cs}0}}")),
        // `\errorstopmode` would make the engine ask the terminal at the next
        // error, so the probe puts batch mode back before the line ends.
        P::Command(Syntax::Interaction(_)) => t(format!("{cs}\\edef\\zR{{\\the\\interactionmode}}\\batchmode")),
        P::Command(Syntax::Token) => t(format!("{cs}\\relax\\edef\\zR{{done}}")),
        P::Command(Syntax::Internal) => t(format!("\\count%I%=%N% {cs}\\count%I% \\edef\\zR{{done}}")),
        P::Command(Syntax::UMathCharDef { num: false }) => t(format!("{cs}\\zq=0 1 65 \\edef\\zR{{\\meaning\\zq}}")),
        P::Command(Syntax::UMathCharDef { num: true }) => t(format!("{cs}\\zq=%N% \\edef\\zR{{\\meaning\\zq}}")),
        P::Command(_) => Err("a stomach command whose effect is the page, the PDF or the terminal"),
        P::Accent => Err("an accent the typesetter builds, which needs a font with the character"),
        P::Unmodeled | P::AlignMark | P::AlignTab => {
            Err("left alone on purpose: a meaning of its own for `\\ifx`, nothing else")
        }
    }
}

/// The value a register of this kind is given.
fn register_value(k: RegKind) -> &'static str {
    match k {
        RegKind::Count | RegKind::Char | RegKind::MathChar | RegKind::UMathChar => "%N%",
        RegKind::Dimen => "%D%",
        RegKind::Skip => "%D% plus 1fil",
        RegKind::MuSkip => "3mu",
        RegKind::Toks => "{ab}",
        RegKind::Box => "\\hbox{}",
        RegKind::Read | RegKind::Write => "%N%",
    }
}

/// The probe for a conditional: run it, and record which branch was taken.
fn conditional(name: &str, c: Cond) -> Result<Template, &'static str> {
    let cs = format!("\\{name}");
    let branch = "\\def\\zR{T}\\else\\def\\zR{F}\\fi";
    let both = |setup: &str, test: String| Ok(Template::new(format!("{setup}{cs}{test}{branch}")));
    match c {
        Cond::True | Cond::False => both("", String::new()),
        Cond::IfX => both("\\def\\za{x}\\def\\zb{x}", "\\za\\zb".into()),
        Cond::Defined => both("", "\\zabsent".into()),
        Cond::Csname => both("", " relax\\endcsname".into()),
        Cond::Num | Cond::AbsNum => both("", "-%N%>0 ".into()),
        Cond::Dim | Cond::AbsDim => both("", "-%D%>0pt ".into()),
        Cond::Odd => both("", "%N% ".into()),
        Cond::Chars => both("", "AB".into()),
        Cond::Catcodes => both("", "AB".into()),
        Cond::Case => Ok(Template::new(format!(
            "{cs}%N% \\def\\zR{{a}}\\or\\def\\zR{{b}}\\or\\def\\zR{{c}}\\else\\def\\zR{{d}}\\fi"
        ))),
        Cond::Eof => both("\\openin%S%=zprobe ", "%S% ".into()),
        Cond::VMode | Cond::HMode | Cond::InnerMode | Cond::MathMode => both("", String::new()),
        Cond::Box => both("\\setbox%I%=\\hbox{}", "%I% ".into()),
        Cond::FontChar => both("", "\\nullfont 65 ".into()),
        Cond::InCsname => both("", String::new()),
        Cond::Primitive => both("", "\\relax".into()),
        Cond::Opaque => Err("a conditional the configuration asks to leave undecided, not a primitive"),
    }
}

/// The probe for an expandable that yields text.
fn convert(name: &str, c: Convert) -> Result<Template, &'static str> {
    let cs = format!("\\{name}");
    let t = |s: String| Ok(Template::new(s));
    let plain = |arg: &str| Ok(Template::new(format!("\\edef\\zR{{[{cs}{arg}]}}")));
    match c {
        Convert::EtexRevision | Convert::PdftexRevision | Convert::PdftexBanner | Convert::XetexRevision => plain(""),
        Convert::CreationDate | Convert::NormalDeviate => plain(""),
        Convert::UniformDeviate => plain(" 1"),
        Convert::FontName => plain("\\nullfont"),
        Convert::FontId => plain("\\nullfont"),
        Convert::StrCmp => plain("{ab}{ac}"),
        Convert::EscapeHex => plain("{AB}"),
        Convert::UnescapeHex => plain("{4142}"),
        Convert::EscapeString => plain("{a(b}"),
        Convert::EscapeName => plain("{a b}"),
        Convert::FileSize | Convert::FileModDate => plain("{zprobe.tex}"),
        Convert::FileDump => plain(" offset 0 length 2 {zprobe.tex}"),
        Convert::MdFiveSum => plain("{abc}"),
        Convert::Match => plain("{b+}{abbbc}"),
        Convert::LastMatch => t(format!("\\edef\\zR{{[\\pdfmatch{{b+}}{{abbbc}}][{cs}0]}}")),
        Convert::PdfFontSize | Convert::PdfFontObjNum | Convert::PdfFontName => {
            t(format!("\\font\\zf=cmr10 \\edef\\zR{{[{cs}\\zf]}}"))
        }
        Convert::InsertHt => plain(" 1"),
        Convert::ColorStackInit => plain("{0 g}"),
        Convert::Mark => plain(""),
        Convert::Marks => plain("0"),
        Convert::Primitive => t(format!("\\def\\string{{oops}}\\edef\\zR{{[{cs}\\string A]}}")),
        Convert::Uchar { catcode: false } => plain(" 65"),
        Convert::Uchar { catcode: true } => plain(" 65 12"),
        Convert::PageRef => Err("names a page object, which a run that ships out no page has not made"),
        Convert::XFormName => Err("names a form object, which this run never creates"),
        Convert::ImageBBox => Err("needs an image the run has read"),
        Convert::MarginKern => Err("reads a kern protrusion left in a box the page builder made"),
        Convert::Xetex(_) => Err("queries a loaded OpenType font, which INITEX has not loaded"),
    }
}

/// The probe for an internal quantity `\the` can read.
fn last_item(name: &str, item: LastItem) -> Result<Template, &'static str> {
    let cs = format!("\\{name}");
    let read = |arg: &str| Ok(Template::new(format!("\\edef\\zR{{[\\the{cs}{arg}]}}")));
    let setup = |pre: &str, arg: &str| Ok(Template::new(format!("{pre}\\edef\\zR{{[\\the{cs}{arg}]}}")));
    match item {
        LastItem::Penalty | LastItem::Kern | LastItem::Skip | LastItem::NodeType | LastItem::Badness => read(""),
        LastItem::InputLineNo
        | LastItem::EtexVersion
        | LastItem::PdftexVersion
        | LastItem::XetexVersion
        | LastItem::LuatexVersion => read(""),
        LastItem::GroupLevel | LastItem::GroupType | LastItem::IfLevel | LastItem::IfType | LastItem::IfBranch => {
            setup("\\iftrue", " \\fi")
        }
        LastItem::GlueStretch | LastItem::GlueShrink | LastItem::GlueStretchOrder | LastItem::GlueShrinkOrder => {
            setup("\\skip%I%=%D% plus 2fil minus 3pt ", "\\skip%I%")
        }
        LastItem::GlueToMu => setup("\\skip%I%=%D% plus 2fil ", "\\skip%I%"),
        LastItem::MuToGlue => setup("\\muskip%I%=3mu plus 2fil ", "\\muskip%I%"),
        LastItem::FontCharWd | LastItem::FontCharHt | LastItem::FontCharDp | LastItem::FontCharIc => {
            setup("\\font\\zf=cmr10 ", "\\zf 65 ")
        }
        LastItem::ParShapeLength | LastItem::ParShapeIndent | LastItem::ParShapeDimen => {
            setup("\\parshape=2 1pt 2pt 3pt 4pt ", "2 ")
        }
        LastItem::ElapsedTime | LastItem::RandomSeed | LastItem::ShellEscape => read(""),
        LastItem::LastXPos | LastItem::LastYPos => read(""),
        LastItem::Xetex(_) => Err("queries a loaded OpenType font, which INITEX has not loaded"),
        LastItem::PdfPageCount => Err("counts the pages of a PDF file the run has read"),
    }
}

// Building the document.

#[derive(Clone)]
struct Case {
    name: String,
    primitive: Primitive,
    verdict: Verdict,
    dim: Dim,
    /// What the probe reads: the primitive's meaning, or its behavior.
    kind: &'static str,
    /// The filled body, one line long, before the context wraps it.
    body: String,
    /// Which edge value the body was filled with, for the report.
    note: String,
}

impl Case {
    fn label(&self) -> String {
        let note = if self.note.is_empty() { String::new() } else { format!(" [{}]", self.note) };
        format!("\\{} ({:?}, {:?}, {}, {}{})", self.name, self.primitive, self.verdict, self.kind, self.dim.tag(), note)
    }
}

/// The `#` of a macro body has to be doubled when the body is read as a
/// replacement text (tex.web § 477).
fn double_hashes(body: &str) -> String {
    body.replace('#', "##")
}

/// Wraps a probe body in its context.  `index` is the probe's place in the
/// batch, which names the file the [`Dim::File`] context reads.
fn wrap(dim: Dim, body: &str, index: usize, deviate: &str) -> (String, Option<(String, String)>) {
    match dim {
        Dim::Plain => (body.to_string(), None),
        Dim::Undecided => (format!("\\ifnum{deviate} 1=0 {body}\\else\\def\\zR{{no}}\\fi"), None),
        Dim::GlobalDefs => (format!("\\begingroup\\globaldefs=1 {body}\\endgroup"), None),
        Dim::Group => (format!("\\begingroup{body}\\endgroup"), None),
        Dim::Unpinned => (body.to_string(), None),
        Dim::File => {
            let file = format!("zb{index}");
            (format!("\\input {file} "), Some((format!("{file}.tex"), format!("{body}%\n"))))
        }
        Dim::Expansion => (format!("\\def\\zm{{{}}}\\zm", double_hashes(body)), None),
        Dim::Rescan => (format!("\\scantokens{{{body}}}"), None),
        Dim::HMode => (format!("\\setbox1=\\hbox{{{body}%WITNESS%}}"), None),
        Dim::VMode => (format!("\\setbox1=\\vbox{{{body}%WITNESS%}}"), None),
    }
}

/// The one line a case becomes.
fn line_for(case: &Case, index: usize, deviate: &str) -> (String, Option<(String, String)>) {
    let (wrapped, extra) = wrap(case.dim, &case.body, index, deviate);
    // `\\write` expands its text again (tex.web § 1368), which would undo a
    // `\\noexpand` the probe is testing, so the value is detokenized instead.
    // The escape character is put back first so both sides print it the same.
    let mut payload = format!("{WITNESS_X}{WITNESS_Y}{WITNESS_Z}\\newlinechar=-1 \\escapechar=92 ");
    for slot in SLOTS {
        payload.push_str(&format!(
            "\\immediate\\write9{{Q{index}{slot}:\\expandafter\\detokenize\\expandafter{{\\{slot}}}}}"
        ));
    }
    // A witness set inside a box has to be read inside it too: the box group
    // takes the definition back at its closing brace (tex.web § 1086).
    let line = if wrapped.contains("%WITNESS%") {
        wrapped.replace("%WITNESS%", &payload)
    } else {
        format!("{wrapped}{payload}")
    };
    // A probe runs inside a box of its own: the outer vertical mode is left
    // once something is typeset (tex.web § 1090) and never comes back, so a
    // probe that starts a paragraph would change the mode every later probe
    // sees.
    (format!("\\setbox254=\\vbox{{{RESET}{line}}}%"), extra)
}

// Running.

/// A directory of its own for every batch, under `target/` so nothing is
/// written to a tmpfs, and emptied first so no probe reads the last one's log.
fn scratch(tag: &str) -> PathBuf {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("target").join("compliance").join(tag);
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).expect("a scratch directory");
    root
}

fn binary(engine: Engine) -> &'static str {
    match engine {
        Engine::XeTeX => "xetex",
        Engine::LuaTeX => "luatex",
        _ => "pdftex",
    }
}

fn available(engine: Engine) -> bool {
    which::which(binary(engine)).is_ok()
}

/// The files every batch reads: a fixed-size file for the file queries, a file
/// `\input` reads, and one that ends early.
fn fixtures(dir: &Path) {
    std::fs::write(dir.join("zprobe.tex"), "hello\n").unwrap();
    std::fs::write(dir.join("zin.tex"), "\\def\\zin{IN}%\n").unwrap();
    std::fs::write(dir.join("zend.tex"), "\\def\\zend{E1}\\endinput\\def\\zend{E2}%\n").unwrap();
}

/// What the engine wrote for each `Q⟨index⟩⟨slot⟩:` marker.
fn engine_answers(engine: Engine, dir: &Path, stem: &str) -> BTreeMap<(usize, String), String> {
    let mut args: Vec<&str> = vec!["-ini", "-interaction=batchmode"];
    if engine != Engine::LuaTeX {
        args.insert(1, "-etex");
    }
    let file = format!("{stem}.tex");
    args.push(&file);
    let _ = std::process::Command::new(binary(engine))
        .args(&args)
        .current_dir(dir)
        .env("SOURCE_DATE_EPOCH", "1767268800")
        .env("FORCE_SOURCE_DATE", "1")
        .output();
    let mut out = BTreeMap::new();
    let Ok(text) = std::fs::read_to_string(dir.join("zout.tex")) else { return out };
    for line in text.lines() {
        let Some(rest) = line.strip_prefix('Q') else { continue };
        let Some((head, value)) = rest.split_once(':') else { continue };
        let at = head.find(|c: char| c.is_ascii_alphabetic()).unwrap_or(head.len());
        let (index, slot) = head.split_at(at);
        let Ok(index) = index.parse::<usize>() else { continue };
        out.insert((index, slot.to_string()), value.to_string());
    }
    out
}

/// Every text satex gave a macro on a line, with whether it was certain.
fn satex_answers(analysis: &Analysis, main: &Path) -> BTreeMap<(u32, String), Vec<(String, bool)>> {
    let mut out: BTreeMap<(u32, String), Vec<(String, bool)>> = BTreeMap::new();
    // The engine reads the answer where the witnesses are.  A local answer
    // made deeper than they are was taken back when its group ended, as when
    // `\outer`'s recovery closes the probe's box early.
    let mut witness_depth: BTreeMap<u32, u16> = BTreeMap::new();
    for def in &analysis.facts.defs {
        if ["zX", "zY", "zZ"].contains(&analysis.interner.name(def.name)) && def.mac.is_some() {
            witness_depth.insert(def.span.line, def.depth);
        }
    }
    for def in &analysis.facts.defs {
        let name = analysis.interner.name(def.name).to_string();
        if name == "zR" && !def.global && witness_depth.get(&def.span.line).is_some_and(|d| *d < def.depth) {
            continue;
        }
        // Only a real definition counts: the reset `\\let`s the slots away so a
        // probe that fails to set one cannot read the last probe's value.
        if !SLOTS.contains(&name.as_str()) || def.mac.is_none() {
            continue;
        }
        if analysis.files.get(usize::from(def.span.file)).is_some_and(|f| Path::new(&f.path) != main) {
            continue;
        }
        let text = def
            .mac
            .as_ref()
            .map(|m| satex::tex::detokenize(&m.replacement_text, &analysis.interner))
            .unwrap_or_default();
        let widened = !def.certain || text.contains('\u{2}');
        out.entry((def.span.line, name)).or_default().push((text, !widened));
    }
    out
}

/// Whitespace and the `##` a `\write` doubles (tex.web § 1368) carry no
/// meaning for the comparison, so both sides are read without them.
fn normalize(text: &str) -> String {
    text.replace("##", "#").split_whitespace().collect()
}

// The divergences this suite found and that are not fixed yet.

/// Each entry names a divergence this suite found, where it lives, and why
/// the engine is right.  Nothing here weakens a comparison: every probe is
/// still run and still compared, the entry only says which open bug a failure
/// belongs to.  A failure that matches no entry fails the test that found it,
/// an entry that stops matching fails
/// [`no_known_divergence_was_fixed`], and the list being non-empty at all
/// fails [`known_divergences_are_open_bugs`], so the suite stays red until
/// they are fixed.
///
/// A matcher is looked for in `" ⟨primitive⟩ ⟨dimension⟩ ⟨what disagreed⟩"`.
const KNOWN: &[(&str, &str)] = &[
    // Primitives classified as a plain parameter that are not one.
    // Quantities the mode or the page builder owns.
    // Reading and printing.
    // Widenings that outlive what caused them, or that the verdict says
    // should not happen at all.
];

/// Which entry of [`KNOWN`], if any, a failure is.  The text a matcher is
/// looked for in is `" ⟨primitive⟩ ⟨dimension⟩ ⟨what disagreed⟩"`, so a
/// matcher that names a primitive carries the space before it and one name is
/// never swallowed by the tail of another.
fn known_for(name: &str, dim: Dim, signature: &str) -> Option<usize> {
    let text = format!(" {name} {} {signature}", dim.tag());
    KNOWN.iter().position(|(matcher, _)| text.contains(matcher))
}

/// Failures are grouped by what disagreed, not by which probe hit it: one
/// divergence in a witness every probe reads would otherwise bury the rest.
#[derive(Default)]
struct Report {
    failures: BTreeMap<String, (usize, Vec<String>)>,
    known: BTreeMap<usize, usize>,
    checked: usize,
    widened: usize,
}

impl Report {
    fn fail(&mut self, case: &Case, signature: String, example: String) {
        if let Some(at) = known_for(&case.name, case.dim, &signature) {
            *self.known.entry(at).or_default() += 1;
            return;
        }
        let entry = self.failures.entry(signature).or_insert((0, Vec::new()));
        entry.0 += 1;
        if entry.1.len() < 4 {
            entry.1.push(example);
        }
    }

    fn count(&self) -> usize {
        self.failures.values().map(|(n, _)| n).sum()
    }
}

/// Compares one slot.  Every disagreement is pushed onto the
/// report with enough of the probe to reproduce it.
fn compare(report: &mut Report, case: &Case, slot: &str, engine: &str, satex: Option<&Vec<(String, bool)>>) {
    let Some(bodies) = satex else {
        // Neither side has a macro to read: the engine's answer is the slot
        // itself, left unexpanded.
        if slot == "zR" && engine.trim() == "\\zR" {
            report.checked += 1;
            return;
        }
        report.fail(
            case,
            format!("{slot}: satex never set it, the engine gave {engine:?}"),
            format!("{} {}", case.label(), case.body),
        );
        return;
    };
    report.checked += 1;
    let want = normalize(engine);
    let certain: Vec<&String> = bodies.iter().filter(|(_, c)| *c).map(|(t, _)| t).collect();
    let widened = certain.len() < bodies.len();
    if widened {
        report.widened += 1;
    }
    let hit = certain.iter().any(|t| normalize(t) == want);
    // Silent wrongness: every path satex took is confident, and none of them
    // is what the engine did.  This holds whatever the verdict is.
    if !hit && !widened {
        let got: Vec<String> = bodies.iter().map(|(t, _)| normalize(t)).collect();
        report.fail(
            case,
            format!("{slot}: satex is confident about {got:?}, the engine gave {want:?}"),
            format!("{} {}", case.label(), case.body),
        );
        return;
    }
    // An exact primitive in a context that cannot force a widening must be
    // exactly right, not merely containing.
    if case.verdict == Verdict::Exact && !case.dim.may_widen() && !(hit && certain.len() == bodies.len()) {
        let got: Vec<String> =
            bodies.iter().map(|(t, c)| format!("{}{}", if *c { "" } else { "?" }, normalize(t))).collect();
        report.fail(
            case,
            format!("{slot}: verdict Exact but satex gave {got:?} for the engine's {want:?}"),
            format!("{} {}", case.label(), case.body),
        );
    }
}

/// Runs one batch of cases through the engine and through satex, and folds the
/// comparison into `report`.
fn run_batch(engine: Engine, tag: &str, batch: &[Case], deviate: &str, report: &mut Report, retry: bool) -> Vec<Case> {
    let dir = scratch(tag);
    fixtures(&dir);
    let mut source = String::from(PRELUDE);
    source.push('\n');
    let mut at = BTreeMap::new();
    for (index, case) in batch.iter().enumerate() {
        let (line, extra) = line_for(case, index, deviate);
        if let Some((name, text)) = extra {
            std::fs::write(dir.join(name), text).unwrap();
        }
        // Line 1 is the prelude, so the first probe is on line 2.
        at.insert(index, (index as u32 + 2, line.clone()));
        source.push_str(&line);
        source.push('\n');
    }
    source.push_str("\\immediate\\closeout9 \\end\n");

    let stem = "zbatch";
    let main = dir.join(format!("{stem}.tex"));
    // Line 1 differs for LuaTeX, and only line 1, so the probes stay on the
    // same lines in the engine's file and in satex's source.
    let on_disk = if engine == Engine::LuaTeX {
        source.replacen(PRELUDE, &format!("{PRELUDE}{LUA_PRELUDE}"), 1)
    } else {
        source.clone()
    };
    std::fs::write(&main, &on_disk).unwrap();
    let engine_out = engine_answers(engine, &dir, stem);
    if engine_out.is_empty() {
        // A probe can take the engine down with it (LuaTeX panics on a
        // `\\luabytecode` register it has not filled), which would lose the
        // whole batch.  Split and let the culprit name itself.
        if retry {
            return batch.to_vec();
        }
        report.fail(
            &batch[0],
            format!("{}: the engine did not finish, so the probe could not be run", binary(engine)),
            format!("{} {}", batch[0].label(), batch[0].body),
        );
        return Vec::new();
    }

    let cfg = Config {
        engine: Some(engine),
        kernel: Some(Kernel::None),
        // The oracle is started with `-interaction=batchmode`, and the
        // option is what `\interactionmode` reads (tex.web § 1337).
        interaction: Interaction::Batchmode,
        load: Load { packages: false, classes: false, format: false, ..Default::default() },
        texmf: Texmf { kpsewhich: false, ..Default::default() },
        ..crate::support::config()
    };
    let analysis = Machine::analyze(&source, Some(&main), &cfg);
    let satex_out = satex_answers(&analysis, &main);
    let lines: BTreeSet<u32> = analysis
        .facts
        .diagnostics
        .iter()
        .filter(|d| d.code == "unknown-catcode" || d.code == "unknown-char-code" || d.code == "unmodeled-primitive")
        .map(|d| d.span.line)
        .collect();

    let mut again = Vec::new();
    for (index, case) in batch.iter().enumerate() {
        let (line_no, _) = &at[&index];
        // One probe that swallows the rest of its line takes the markers of
        // every later probe with it, so an incomplete batch is split before
        // anything is blamed on it.
        if retry && SLOTS.iter().any(|slot| !engine_out.contains_key(&(index, (*slot).to_string()))) {
            again.push(case.clone());
            continue;
        }
        for slot in SLOTS {
            if slot == "zR" && !case.dim.answer_is_on_the_line() {
                continue;
            }
            let Some(engine_value) = engine_out.get(&(index, slot.to_string())) else {
                // The engine never reached the marker: the probe left it in a
                // state where the rest of the line was swallowed.  Say so
                // rather than pass quietly.
                report.fail(
                    case,
                    format!("{slot}: the engine wrote no marker, so the probe is not self-contained"),
                    format!("{} {}", case.label(), case.body),
                );
                continue;
            };
            compare(report, case, slot, engine_value, satex_out.get(&(*line_no, slot.to_string())));
        }
        // An Unsupported primitive met with an operand it cannot pin down has
        // to widen *and* say so.
        if case.verdict == Verdict::Unsupported && case.dim == Dim::Unpinned {
            let said = lines.contains(line_no);
            let widened = SLOTS
                .iter()
                .any(|slot| satex_out.get(&(*line_no, (*slot).to_string())).is_some_and(|b| b.iter().any(|(_, c)| !c)));
            if !(said && widened) {
                report.fail(
                    case,
                    format!("unsupported with an unpinnable operand, but widened={widened} diagnosed={said}"),
                    format!("{} {}", case.label(), case.body),
                );
            }
        }
    }
    again
}

// The table the cases come from.

/// Every primitive name the engines know, each assigned to the cheapest engine
/// that has it.  This is the whole table from `builtins.rs`, and nothing here
/// names a primitive.
fn table() -> Vec<(Engine, String, Primitive)> {
    let mut seen: BTreeMap<String, (Engine, Primitive)> = BTreeMap::new();
    for engine in [Engine::PdfTeX, Engine::XeTeX, Engine::LuaTeX] {
        let mut interner = satex::tex::Interner::default();
        for (sym, meaning) in builtins::initial_meanings(&mut interner, engine) {
            let Meaning::Primitive(p) = meaning else { continue };
            let name = interner.name(sym).to_string();
            seen.entry(name).or_insert((engine, p));
        }
    }
    seen.into_iter().map(|(name, (engine, p))| (engine, name, p)).collect()
}

/// A name that cannot be written into a probe line as `\name`.
fn writable(name: &str) -> bool {
    !name.is_empty() && !name.contains(char::is_whitespace)
}

fn meaning_case(name: &str, p: Primitive) -> Case {
    Case {
        name: name.to_string(),
        primitive: p,
        verdict: builtins::verdict(p).0,
        dim: Dim::Plain,
        kind: "meaning",
        body: format!("\\edef\\zR{{[\\meaning\\{name}]}}"),
        note: String::new(),
    }
}

fn behavior_case(name: &str, p: Primitive, dim: Dim, template: &Template, with: Fill<'_>, note: &str) -> Case {
    Case {
        name: name.to_string(),
        primitive: p,
        verdict: builtins::verdict(p).0,
        dim,
        kind: "behavior",
        body: template.fill(with).replace("%C%", "`\\A"),
        note: note.to_string(),
    }
}

fn full() -> bool {
    std::env::var("SATEX_COMPLIANCE").is_ok_and(|v| v == "full")
}

/// One case in `n` when the default suite is running, all of them under
/// `SATEX_COMPLIANCE=full`.
fn slice<T>(cases: Vec<T>, n: usize) -> Vec<T> {
    if full() {
        return cases;
    }
    cases.into_iter().enumerate().filter(|(i, _)| i % n == 0).map(|(_, c)| c).collect()
}

fn by_engine(cases: Vec<(Engine, Case)>) -> Vec<(Engine, Vec<Case>)> {
    let mut out: Vec<(Engine, Vec<Case>)> = Vec::new();
    for (engine, case) in cases {
        match out.iter_mut().find(|(e, _)| *e == engine) {
            Some((_, list)) => list.push(case),
            None => out.push((engine, vec![case])),
        }
    }
    out
}

/// `\uniformdeviate 1` is 0 in every engine, and satex cannot pin it down: the
/// name is read from the table, not written here.
fn deviate(engine: Engine) -> String {
    let mut interner = satex::tex::Interner::default();
    for (sym, meaning) in builtins::initial_meanings(&mut interner, engine) {
        if meaning == Meaning::Primitive(Primitive::Convert(Convert::UniformDeviate)) {
            return format!("\\{}", interner.name(sym));
        }
    }
    String::from("\\pdfuniformdeviate")
}

/// Runs the cases, engine by engine, in batches small enough that one probe's
/// mistake cannot hide the next one's.
fn run(tag: &str, cases: Vec<(Engine, Case)>) -> Report {
    const BATCH: usize = 24;
    let mut report = Report::default();
    for (engine, cases) in by_engine(cases) {
        if !available(engine) {
            continue;
        }
        let deviate = deviate(engine);
        let mut again = Vec::new();
        for (n, batch) in cases.chunks(BATCH).enumerate() {
            again.extend(run_batch(
                engine,
                &format!("{tag}-{}-{n}", binary(engine)),
                batch,
                &deviate,
                &mut report,
                true,
            ));
        }
        for (n, case) in again.into_iter().enumerate() {
            let tag = format!("{tag}-{}-alone-{n}", binary(engine));
            run_batch(engine, &tag, std::slice::from_ref(&case), &deviate, &mut report, false);
        }
    }
    report
}

fn finish(what: &str, report: Report) -> Report {
    println!(
        "{what}: {} comparisons, {} widened, {} known divergences",
        report.checked,
        report.widened,
        report.known.values().sum::<usize>()
    );
    for (at, times) in &report.known {
        println!("  {times}x \\{}: {}", KNOWN[*at].0.trim(), KNOWN[*at].1);
    }
    if !report.failures.is_empty() {
        let mut lines = Vec::new();
        for (signature, (times, examples)) in &report.failures {
            lines.push(format!("{times}x {signature}\n     {}", examples.join("\n     ")));
        }
        panic!(
            "{} probes disagree with the engine outside the known list, {} distinct:\n{}",
            report.count(),
            report.failures.len(),
            lines.join("\n")
        );
    }
    report
}

// The case sets.

/// Every primitive, whatever its verdict: `\meaning` reaches all of them,
/// including the ones satex leaves alone, because `\ifx` compares meanings
/// and a wrong one is wrong for every package that asks.
fn meaning_cases() -> Vec<(Engine, Case)> {
    table().into_iter().filter(|(_, n, _)| writable(n)).map(|(e, n, p)| (e, meaning_case(&n, p))).collect()
}

/// The behavioral probe for every primitive that has one, at the outer
/// vertical mode.
fn behavior_cases() -> Vec<(Engine, Case)> {
    let mut cases = Vec::new();
    for (engine, name, p) in table() {
        if !writable(&name) {
            continue;
        }
        if let Ok(template) = template(&name, p) {
            let index = if template.has("%S%") || template.has("%T%") { "3" } else { "7" };
            let with = Fill { index, ..Fill::default() };
            cases.push((engine, behavior_case(&name, p, Dim::Plain, &template, with, "")));
        }
    }
    cases
}

/// The contexts crossed with the primitives they can apply to.
fn context_cases() -> Vec<(Engine, Case)> {
    let mut cases = Vec::new();
    for (engine, name, p) in table() {
        if !writable(&name) {
            continue;
        }
        let Ok(template) = template(&name, p) else { continue };
        for dim in CONTEXTS {
            // An unpinnable index only matters where the template has one.
            if dim == Dim::Unpinned && !template.has("%I%") && !template.has("%S%") && !template.has("%T%") {
                continue;
            }
            let index = match (dim, engine) {
                (Dim::Unpinned, Engine::PdfTeX) => "\\pdfuniformdeviate 1 ",
                (Dim::Unpinned, _) => "\\uniformdeviate 1 ",
                _ if template.has("%S%") || template.has("%T%") => "3",
                _ => "7",
            };
            cases.push((engine, behavior_case(&name, p, dim, &template, Fill { index, ..Fill::default() }, "")));
        }
    }
    slice(cases, 7)
}

/// The boundaries tex.web names, for every probe that takes a number, a
/// dimension or a register index.
fn edge_cases() -> Vec<(Engine, Case)> {
    let mut cases = Vec::new();
    for (engine, name, p) in table() {
        if !writable(&name) {
            continue;
        }
        let Ok(template) = template(&name, p) else { continue };
        if template.has("%N%") {
            for int in EDGE_INTS {
                let with = Fill { int, ..Fill::default() };
                cases.push((engine, behavior_case(&name, p, Dim::Plain, &template, with, int)));
            }
        }
        if template.has("%D%") {
            for dimen in EDGE_DIMENS {
                let with = Fill { dimen, ..Fill::default() };
                cases.push((engine, behavior_case(&name, p, Dim::Plain, &template, with, dimen)));
            }
        }
        // tex.web § 433: a register index is eight bits, an input stream four.
        // Stream 16 is the terminal, which a batch run has no answer for, so
        // the out-of-range stream is 99 instead.
        let indices: &[&str] = if template.has("%T%") {
            // `\\read` from stream 16, or from a bad number the engine turns
            // into stream 0, reads the terminal and ends a batch run.
            &["0", "15"]
        } else if template.has("%S%") {
            &["0", "15", "99"]
        } else {
            &["0", "15", "16", "255"]
        };
        if template.has("%I%") || template.has("%S%") || template.has("%T%") {
            for index in indices {
                let with = Fill { index, ..Fill::default() };
                cases.push((engine, behavior_case(&name, p, Dim::Plain, &template, with, index)));
            }
        }
    }
    slice(cases, 11)
}

// The tests.

#[test]
fn every_primitive_means_what_the_engine_says() {
    finish("meanings", run("meaning", meaning_cases()));
}

#[test]
fn every_probed_primitive_behaves_like_the_engine() {
    finish("behavior", run("behavior", behavior_cases()));
}

/// The engine's answer is ground truth in every context, so containment is the
/// same relation there as anywhere else.
#[test]
fn every_probed_primitive_stays_sound_in_context() {
    finish("contexts", run("context", context_cases()));
}

/// These are where the `\count` top and `\ifeof` stream bugs lived.
#[test]
fn numeric_primitives_agree_at_every_edge() {
    finish("edges", run("edge", edge_cases()));
}

/// The known list must not rot: every entry has to still be a divergence.  An
/// entry that no longer matches has been fixed and belongs out of the list,
/// not kept as a standing excuse.  Some entries only show up in a part of the
/// cross product the default run samples away, so the question is only
/// answerable under `SATEX_COMPLIANCE=full`, and the default run says so
/// instead of guessing.
#[test]
fn no_known_divergence_was_fixed() {
    if !available(Engine::PdfTeX) {
        return;
    }
    if !full() {
        println!("SATEX_COMPLIANCE=full checks whether a known divergence was fixed");
        return;
    }
    let mut hit: BTreeSet<usize> = BTreeSet::new();
    for (tag, cases) in [
        ("known-meaning", meaning_cases()),
        ("known-behavior", behavior_cases()),
        ("known-context", context_cases()),
        ("known-edge", edge_cases()),
    ] {
        // A failure outside the list is reported by the test that owns it.
        hit.extend(run(tag, cases).known.into_keys());
    }
    let stale: Vec<&str> =
        KNOWN.iter().enumerate().filter(|(at, _)| !hit.contains(at)).map(|(_, (matcher, _))| *matcher).collect();
    assert!(stale.is_empty(), "these known divergences no longer happen, take them out of KNOWN: {stale:?}");
}

/// The divergences are bugs, not a budget.  This fails while any is open, so
/// the suite is red until the interpreter agrees with the engine, and the
/// other tests can still be read for anything new.
#[test]
fn known_divergences_are_open_bugs() {
    let mut lines = Vec::new();
    for (matcher, why) in KNOWN {
        lines.push(format!("  {}: {why}", matcher.trim()));
    }
    assert!(
        KNOWN.is_empty(),
        "{} divergences from the engine are open, each found by a probe in this file:\n{}",
        KNOWN.len(),
        lines.join("\n")
    );
}

/// The hole has to be visible.  A primitive with no behavioral probe is listed
/// with the reason, and the count is printed, so nobody has to guess how much
/// of the table the suite reaches.
#[test]
fn unprobed_primitives_are_listed_with_a_reason() {
    let mut probed = 0usize;
    let mut unprobed: BTreeMap<&'static str, Vec<String>> = BTreeMap::new();
    for (_, name, p) in table() {
        if !writable(&name) {
            unprobed.entry("the name is not writable as `\\name` on one line").or_default().push(name);
            continue;
        }
        match template(&name, p) {
            Ok(_) => probed += 1,
            Err(reason) => unprobed.entry(reason).or_default().push(name),
        }
    }
    let missing: usize = unprobed.values().map(Vec::len).sum();
    println!("{probed} primitives have a behavioral probe, {missing} do not:");
    for (reason, mut names) in unprobed {
        names.sort();
        println!("  {} ({reason}): {}", names.len(), names.join(" "));
    }
    // Every primitive is reached by the meaning probe whatever else it gets.
    assert!(probed + missing > 900, "the table shrank to {}", probed + missing);
}

/// Skips cleanly when no engine is installed, as the other engine tests do.
#[test]
fn the_suite_skips_without_an_engine() {
    if !available(Engine::PdfTeX) {
        println!("no pdftex: the compliance matrix is skipped");
    }
}
